// WatchUnlisted is a free log subscription operation binding the contract event 0x398bd90ce129393b9155d48dccffb325e671f45c4250de457462a019268ff1f0.
//
// Solidity: event Unlisted(uint256 indexed tokenId, address indexed seller)
func (_GeoyuanCard *GeoyuanCardFilterer) WatchUnlisted(opts *bind.WatchOpts, sink chan<- *GeoyuanCardUnlisted, tokenId []*big.Int, seller []common.Address) (event.Subscription, error) {

	var tokenIdRule []interface{}
	for _, tokenIdItem := range tokenId {
		tokenIdRule = append(tokenIdRule, tokenIdItem)
	}
	var sellerRule []interface{}
	for _, sellerItem := range seller {
		sellerRule = append(sellerRule, sellerItem)
	}

	logs, sub, err := _GeoyuanCard.contract.WatchLogs(opts, "Unlisted", tokenIdRule, sellerRule)
	if err != nil {
		return nil, err
	}
	return event.NewSubscription(func(quit <-chan struct{}) error {
		defer sub.Unsubscribe()
		for {
			select {
			case log := <-logs:
				// New log arrived, parse the event and forward to the user
				event := new(GeoyuanCardUnlisted)
				if err := _GeoyuanCard.contract.UnpackLog(event, "Unlisted", log); err != nil {
					// If the signature doesn't match, skip this log.
					if errors.Is(err, bind.ErrEventSignatureMismatch) {
						continue
					}
					return err
				}
				event.Raw = log

				select {
				case sink <- event:
				case err := <-sub.Err():
					return err
				case <-quit:
					return nil
				}
			case err := <-sub.Err():
				return err
			case <-quit:
				return nil
			}
		}
	}), nil
}

